                current_depth -= 1
        return max_depth

    result = []
    groups = paren_string.split()
    for group in groups:
        if validate_parentheses(group):
            result.append(calculate_deepest_level(group))
        else:
            raise ValueError("Invalid parentheses format in input string")

    return result

